inline float attackMod(uint32_t sequence){
    const auto it=std::lower_bound(attacks.begin(),attacks.end(),sequence,[](const Attack& a,uint32_t s){return a.sequence<s;});
    return it!=attacks.end()&&it->sequence==sequence?it->mod:1.f;}
inline bool attackKnown(uint32_t sequence){
    const auto it=std::lower_bound(attacks.begin(),attacks.end(),sequence,[](const Attack& a,uint32_t s){return a.sequence<s;});
    return it!=attacks.end()&&it->sequence==sequence;}
inline const Enemy* enemy(const std::array<uint32_t,4>& g){
    const auto it=std::lower_bound(enemies.begin(),enemies.end(),g,[](const Enemy& e,const std::array<uint32_t,4>& k){return e.guid<k;});
    return it!=enemies.end()&&it->guid==g?&*it:nullptr;}
inline int categoryField(const std::array<uint8_t,16>& g){for(const auto& c:categories)if(c.guid==g)return c.field;return -1;}
inline const Perk* perk(uint32_t id){for(const auto& p:perks)if(p.id==id)return &p;return nullptr;}
